from telnetlib import Telnet
from contextlib import contextmanager

AASHELL_PROMPT = b'AaShell>'
TIMEOUT = 10


@contextmanager
def _telnet(host, port):
    telnet = Telnet()
    telnet.open(host, port)
    yield telnet
    telnet.close()


def execute_aashell_command(command, enb_ip='192.168.255.1', aashell_port='15007', command_timeout=TIMEOUT):
    """
    Executes aashell command and returns output
    :param command: command to execute
    :param enb_ip:
    :param aashell_port:
    :return: command output as string
    """
    with _telnet(enb_ip, aashell_port) as telnet_connection:
        telnet_connection.read_until(AASHELL_PROMPT, timeout=TIMEOUT)
        cmd = command + '\n'
        telnet_connection.write(cmd.encode('ascii'))
        command_output = telnet_connection.read_until(AASHELL_PROMPT, timeout=command_timeout)
        output_without_shell_prompt = command_output[: len(command_output) - len(AASHELL_PROMPT)]
    return output_without_shell_prompt
